#
# @lc app=leetcode id=1926 lang=python3
#
# [1926] Nearest Exit from Entrance in Maze
#
from typing import *
from collections import deque
# @lc code=start
class Solution:
    def _isExit(self, position: tuple[int, int], maze: List[List[str]]) -> bool:
        i, j = position
        
        return i == 0 or j == 0 or i == len(maze) - 1 or j == len(maze[0]) - 1
    
    def nearestExit(self, maze: List[List[str]], entrance: List[int]) -> int:
        queue: deque[list[int]] = deque()
        queue.append(entrance + [0])
        
        dirs = ((0, 1), (0, -1), (1, 0), (-1, 0))
        
        iterations = 0
        while len(queue):
            i, j, steps = queue.popleft()
            iterations += 1
            print(iterations)
            if (i != entrance[0] or j != entrance[1]) and self._isExit([i, j], maze):
                return steps

            next_steps = steps + 1
            maze[i][j] = '+'
            for dir in dirs:
                next_i = i + dir[0]
                next_j = j + dir[1]
                if 0 <= next_i < len(maze) and 0 <= next_j < len(maze[0]) and maze[next_i][next_j] != '+':
                    maze[next_i][next_j] = '+'
                    queue.append([next_i, next_j, next_steps])
                    
        return -1
        
# @lc code=end

